],"abilities":[{"name":"Warden Tactics","description":"Coordinates emergency bridge repairs under dangerous conditions.","category":"mental"}]}],"relationships":[{"id":"rel_isolde_mentored_by_marek","source_character_id":"chr_marek_osse","target_character_id":"chr_isolde_vane","relationship_type":"mentor","description":"Marek Osse acts as a guarded mentor to Isolde Vane, guiding her while concealing his role in her mother's disappearance."},{"id":"rel_isolde_corvin_rival","source_character_id":"chr_isolde_vane","target_character_id":"chr_corvin_halewind","relationship_type":"rival","description":"Isolde Vane opposes Corvin Halewind's rising tolls, which block the repairs she believes can save the realm."},{"id":"rel_corvin_isolde_enemy","source_character_id":"chr_corvin_halewind","target_character_id":"chr_isolde_vane","relationship_type":"enemy","description":"Corvin Halewind sees Isolde Vane's repairs as a threat to Cartel toll revenue and works to obstruct her."},{"id":"rel_bram_isolde_mentor","source_character_id":"chr_bram_cinderlock","target_character_id":"chr_isolde_vane","relationship_type":"mentor","description":"Bram Cinderlock teaches Isolde Vane the craft of cloudstone braiding, though he resists her innovative designs."},{"id":"rel_wren_isolde_ally","source_character_id":"chr_wren_tillerbrook","target_character_id":"chr_isolde_vane","relationship_type":"ally","description":"Wren Tillerbrook joins Isolde Vane's mission, offering mechanical ingenuity in exchange for passage beyond the Hollow."},{"id":"rel_wren_corvin_enemy","source_character_id":"chr_wren_tillerbrook","target_character_id":"chr_corvin_halewind","relationship_type":"enemy","description":"Wren Tillerbrook resents Corvin Halewind for enforcing the Grain Levy that threatens her family's mill."}]}
