e_location_id":"loc_emberroost","faction_id":"fac_bridge_wardens","motivation":"To keep her companions alive and honour the Warden oath to protect those who cross bridges.","goal":"Ensure every member of the expedition returns home across the final skybridge.","flaw":"Rigid sense of duty that makes her slow to question orders, even bad ones.","internal_conflict":"Her oath to protect clashes with her growing suspicion that the mission itself is harming people.","external_conflict":"Corvin's orders endanger the party, and the rule against open flame limits her tools in the jungle.","arc":"Sable moves from unquestioning obedience to open defiance, realizing true duty lies with people rather than patrons.","personality_traits":["stoic","protective","disciplined","blunt"],"abilities":[{"name":"Forge-Hardened Strength","description":"Trained in heavy labour and combat with hammers and cable hooks.","category":"physical"}]}],"relationships":[{"id":"rel_mara_corvin_patron","source_character_id":"chr_mara_vell","target_character_id":"chr_corvin_drax","relationship_type":"rival","description":"Mara Vell is bound by contract to guide Corvin Drax, who bought her debt, and she distrusts his plan to plunder the city while he presses her to reveal the route she has long concealed."},{"id":"rel_corvin_tobias_debt","source_character_id":"chr_corvin_drax","target_character_id":"chr_tobias_wren","relationship_type":"employer","description":"Corvin Drax exploits Tobias Wren's family wind-debt and the Cartel's grain levy to keep the young porter obedient and expendable."},{"id":"rel_ilsa_mara_mentor","source_character_id":"chr_ilsa_quill","target_character_id":"chr_mara_vell","relationship_type":"mentor","description":"Dr. Ilsa Quill once taught Mara Vell at Silverspine Academy and now pushes her former student to share her jungle knowledge, straining their trust."},{"id":"rel_sable_mara_ally","source_character_id":"chr_sable_kest","target_character_id":"chr_mara_vell","relationship_type":"ally","description":"Sable Kest, a fellow Bridge Warden, quietly backs Mara Vell and becomes her closest ally as they protect the party from Corvin's reckless orders."},{"id":"rel_tobias_sable_protege","source_character_id":"chr_tobias_wren","target_character_id":"chr_sable_kest","relationship_type":"friend","description":"Tobias Wren looks up to Sable Kest, who shields him on the trail and helps him find the courage to oppose Corvin Drax."}]}
