tions.","goal":"Earn enough from courier work to clear his family's debt.","flaw":"Impulsive and easily tempted by quick money.","internal_conflict":"He is torn between loyalty to his Cartel-employed family and the conscience that urges him to reveal what he has seen.","external_conflict":"Cartel enforcers watch him, and his debt keeps him under Castor's thumb.","arc":"Pell goes from opportunistic courier to a brave witness, carrying Maren's evidence across the isles at personal risk.","personality_traits":["quick-witted","reckless","loyal","resourceful"],"abilities":[{"name":"Windrunning","description":"Navigates crowded docks and skybridges at speed in rough weather.","category":"physical"}]}],"relationships":[{"id":"rel_maren_castor_rivalry","source_character_id":"chr_maren_voss","target_character_id":"chr_castor_drell","relationship_type":"enemy","description":"Maren Voss opposes Castor Drell, whose tolls starve the Wardens and whose profits depend on the bridges' failures she fights to prevent."},{"id":"rel_maren_oren_ally","source_character_id":"chr_maren_voss","target_character_id":"chr_oren_thale","relationship_type":"ally","description":"Maren Voss relies on Oren Thale's charts to predict ward failures, though she distrusts his timidity."},{"id":"rel_castor_pell_master","source_character_id":"chr_castor_drell","target_character_id":"chr_pell_corvin","relationship_type":"master","description":"Castor Drell holds Pell Corvin's family in wind-debt and uses him as an errand runner, tightening his control as Pell grows suspicious."},{"id":"rel_isolde_castor_opponent","source_character_id":"chr_isolde_march","target_character_id":"chr_castor_drell","relationship_type":"rival","description":"Isolde March resists Castor Drell's grain levy, creating friction that threatens The Hollow's quiet neutrality."},{"id":"rel_pell_maren_informant","source_character_id":"chr_pell_corvin","target_character_id":"chr_maren_voss","relationship_type":"ally","description":"Pell Corvin secretly passes Maren Voss what he has seen of Cartel crews, risking Castor Drell's retaliation."},{"id":"rel_isolde_maren_ally","source_character_id":"chr_isolde_march","target_character_id":"chr_maren_voss","relationship_type":"ally","description":"Isolde March and Maren Voss form a wary partnership, trading grain and labour for bridge repairs against the Cartel."}]}
